-- Table: transaction_customer_receipt_detail
-- Source: accounting_admin_db.sql (3. Sales flow)
--
-- One migration per table. Do not edit this file after it has been applied;
-- add a new migration for later schema changes.

CREATE TABLE IF NOT EXISTS transaction_customer_receipt_detail (
    id                   BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    customer_receipt_id  BIGINT NOT NULL REFERENCES transaction_customer_receipt(id) ON DELETE CASCADE,
    line_number          INTEGER NOT NULL CHECK (line_number > 0),
    sales_invoice_id     BIGINT NOT NULL REFERENCES transaction_sales_invoice(id),
    amount               NUMERIC(18,2) NOT NULL CHECK (amount > 0),
    discount_amount      NUMERIC(18,2) NOT NULL DEFAULT 0 CHECK (discount_amount >= 0),
    notes                TEXT,
    UNIQUE (customer_receipt_id, line_number)
);
